import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { projectLogic } from 'scenes/projectLogic'

import { metricsPipelinesDestroy, metricsPipelinesList } from '../generated/api'
import { MetricsPipelineApi } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelinesLogicValues {
    currentProjectId: number | null // projectLogic
    pipelines: MetricsPipelineApi[]
    pipelinesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelinesLogicActions {
    deletePipeline: (id: string) => string
    deletePipelineFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    deletePipelineSuccess: (
        pipelines: MetricsPipelineApi[],
        payload?: string
    ) => {
        pipelines: MetricsPipelineApi[]
        payload?: string
    }
    loadPipelines: () => any
    loadPipelinesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPipelinesSuccess: (
        pipelines: MetricsPipelineApi[],
        payload?: any
    ) => {
        pipelines: MetricsPipelineApi[]
        payload?: any
    }
}

export type pipelinesLogicType = MakeLogicType<pipelinesLogicValues, pipelinesLogicActions>

export const pipelinesLogic = kea<pipelinesLogicType>([
    path(['products', 'metrics', 'frontend', 'pipelines', 'pipelinesLogic']),
    connect({ values: [projectLogic, ['currentProjectId']] }),
    loaders(({ values }) => ({
        pipelines: [
            [] as MetricsPipelineApi[],
            {
                loadPipelines: async () => {
                    const response = await metricsPipelinesList(String(values.currentProjectId))
                    return response.results
                },
                deletePipeline: async (id: string) => {
                    await metricsPipelinesDestroy(String(values.currentProjectId), id)
                    lemonToast.success('Pipeline deleted')
                    return values.pipelines.filter((pipeline: MetricsPipelineApi) => pipeline.id !== id)
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadPipelines()
    }),
])
